class Solution {
public:
    vector<int> findSubstring(string s, vector<string>& words) {
        vector<int> result;
        if (words.empty() || s.empty()) return result;
        int n = s.size();
        int numWords = (int)words.size();
        int wlen = (int)words[0].size();
        long long totalLen = (long long)numWords * wlen;
        if ((long long)n < totalLen) return result;

        unordered_map<string, int> target;
        for (auto& w : words) target[w]++;

        for (int offset = 0; offset < wlen; offset++) {
            unordered_map<string, int> cur;
            int left = offset;
            int count = 0;
            for (int right = offset; right + wlen <= n; right += wlen) {
                string word = s.substr(right, wlen);
                auto it = target.find(word);
                if (it == target.end()) {
                    cur.clear();
                    count = 0;
                    left = right + wlen;
                } else {
                    cur[word]++;
                    count++;
                    while (cur[word] > it->second) {
                        string leftWord = s.substr(left, wlen);
                        cur[leftWord]--;
                        count--;
                        left += wlen;
                    }
                    if (count == numWords) {
                        result.push_back(left);
                        string leftWord = s.substr(left, wlen);
                        cur[leftWord]--;
                        count--;
                        left += wlen;
                    }
                }
            }
        }
        return result;
    }
};
